class LedgerTest(unittest.TestCase):
    def test_empty_ledger_has_zero_balance(self) -> None:
        self.assertEqual(Ledger().balance(), 0.0)

    def test_single_deposit(self) -> None:
        ledger = Ledger()
        ledger.add(50.0)
        self.assertEqual(ledger.balance(), 50.0)

    def test_deposits_accumulate(self) -> None:
        ledger = Ledger()
        ledger.add(10.0)
        ledger.add(20.0)
        self.assertEqual(ledger.balance(), 30.0)

    def test_refunds_reduce_the_balance(self) -> None:
        ledger = Ledger()
        ledger.add(100.0)
        ledger.add(-40.0)
        self.assertEqual(ledger.balance(), 60.0)

    def test_balance_can_go_negative(self) -> None:
        ledger = Ledger()
        ledger.add(10.0)
        ledger.add(-30.0)
        self.assertEqual(ledger.balance(), -20.0)

    def test_entry_count_tracks_every_addition(self) -> None:
        ledger = Ledger()
        ledger.add(1.0)
        ledger.add(-1.0)
        ledger.add(2.0)
        self.assertEqual(ledger.entry_count(), 3)


